"use client";

import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { AnimatePresence, motion } from "framer-motion";
import { cn } from "@/lib/utils";
import "./checklist.css";

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

/**
 * ══ Checklist ═════════════════════════════════════════════════════
 * A tactile task checklist where checking a row runs off a single harmonic
 * spring with four simultaneous physical readings:
 * 1. Raw Overshoot Fill: Checkbox fill expands from the center and swells past 1.0.
 * 2. Clamped Tick Drawing: The checkmark path stroke walks forward without overshooting.
 * 3. Strikethrough Rule: Delayed line scales horizontally from the text start.
 * 4. Word Ink Fade: Text opacity yields in lockstep with the rule progression.
 *
 * Finishing Kinematics:
 * - When every item is checked, the floor drops out and rows collapse into a natural,
 *   gravity-driven heap with dynamic overhang tilt calculated from text lengths.
 * - Rebounds on impact and auto-resets after 3 seconds, or smoothly interrupts
 *   if any item is unchecked during the fall.
 * ═════════════════════════════════════════════════════════════════
 */

export type ChecklistTheme = "light" | "dark";

export interface ChecklistItem {
  text: string;
  done: boolean;
}

export interface ChecklistProps {
  /** Outer slab corner radius in pixels (default: 20) */
  corner?: number;
  /** Checkbox bounce overshoot amplitude 0..100 (default: 50) */
  bounce?: number;
  /** Checkbox square dimensions in pixels (default: 18) */
  box?: number;
  /** Visual theme mode (default: "light") */
  theme?: ChecklistTheme;
  /** Initial tasks list */
  initialItems?: ChecklistItem[] | string[];
  /** Controlled tasks list */
  items?: ChecklistItem[];
  /** Callback fired when items update */
  onItemsChange?: (items: ChecklistItem[]) => void;
  /** Callback fired when all items are checked and collapse triggers */
  onComplete?: () => void;
  className?: string;
  style?: React.CSSProperties;
}

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
const mix = (a: number, b: number, t: number) => a + (b - a) * t;

const springOf = (tune: number) => ({
  k: 0.08 + (tune / 100) * 0.16,
  d: 0.62 + (tune / 100) * 0.2,
});

function useSpring(target: number, tune = 50, instant = false) {
  const [at, setAt] = useState(target);
  const cur = useRef(target);
  const vel = useRef(0);
  const raf = useRef(0);

  useEffect(() => {
    if (instant) {
      cur.current = target;
      vel.current = 0;
      return;
    }
    const { k, d } = springOf(tune);
    let prev = 0;
    const tick = (t: number) => {
      const dt = prev ? clamp((t - prev) / 16.67, 0, 2.5) : 1;
      prev = t;
      vel.current += (target - cur.current) * k * dt;
      vel.current *= Math.pow(d, dt);
      cur.current += vel.current * dt;
      if (Math.abs(target - cur.current) < 0.02 && Math.abs(vel.current) < 0.02) {
        cur.current = target;
        vel.current = 0;
        setAt(target);
        raf.current = 0;
        return;
      }
      setAt(cur.current);
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf.current);
      raf.current = 0;
    };
  }, [target, tune, instant]);

  return instant ? target : at;
}

const stillness = () =>
  typeof window !== "undefined" &&
  !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

const W = 300;
const PAD = 14;
const ROW = 40;
const BOX = 18;
const CORNER = 20;
const BOUNCE = 50;
const LAG = 0.12;
const RUN = 0.72;
const DROP_MS = 0.46;
const REBOUND = 8;
const FALL_EASE = ["easeIn", "easeOut", "easeIn"] as const;
const HOLD = 3000;
const MAX_LEAN = 6;
const REACH = 40;
const leanOf = (over: number) => MAX_LEAN * (1 - Math.exp(-over / REACH));
const DRIFT = [-5, 4, -2, 5, -3];
const SPAN = W - PAD * 2;
const MID = SPAN / 2;
const sin = (deg: number) => Math.sin((deg * Math.PI) / 180);
const gapFor = (leans: number[], runs: number[]) =>
  1 +
  Math.max(
    0,
    ...leans.slice(1).map((below, i) => {
      const ink = Math.max(runs[i] ?? MID, runs[i + 1] ?? MID);
      return Math.max(0, (ink - MID) * (sin(leans[i]) - sin(below)));
    })
  );

const DEFAULT_TASKS: ChecklistItem[] = [
  { text: "Book the studio", done: false },
  { text: "Send the estimate", done: false },
  { text: "Pick a typeface", done: false },
];
const MAX = 5;

export function Checklist({
  corner = CORNER,
  bounce = BOUNCE,
  box = BOX,
  theme = "light",
  initialItems,
  items: controlledItems,
  onItemsChange,
  onComplete,
  className = "",
  style,
}: ChecklistProps) {
  const isControlled = controlledItems !== undefined;
  const [internalItems, setInternalItems] = useState<ChecklistItem[]>(() => {
    if (initialItems && initialItems.length > 0) {
      return initialItems.map((item) =>
        typeof item === "string" ? { text: item, done: false } : item
      );
    }
    return DEFAULT_TASKS;
  });

  const items = isControlled ? controlledItems : internalItems;
  const [adding, setAdding] = useState(false);
  const [draft, setDraft] = useState("");
  const [runs, setRuns] = useState<number[]>([]);
  const [line, setLine] = useState(20);

  const measure = useCallback((i: number, px: number, tall: number) => {
    setRuns((v) => (v[i] === px ? v : Object.assign([...v], { [i]: px })));
    setLine((v) => (v === tall ? v : tall));
  }, []);

  const still = stillness();
  const r = clamp(corner, 0, 40);
  const side = clamp(Math.round(box), 14, 28);
  const isDark = theme === "dark";

  const fell = items.length > 0 && items.every((t) => t.done);
  const spare = items.length < MAX;

  // Auto-reset when complete after HOLD duration
  useEffect(() => {
    if (!fell) return;
    onComplete?.();
    const id = window.setTimeout(() => {
      const reset = DEFAULT_TASKS.map((t) => ({ ...t, done: false }));
      if (!isControlled) {
        setInternalItems(reset);
      }
      onItemsChange?.(reset);
    }, HOLD);
    return () => window.clearTimeout(id);
  }, [fell, isControlled, onComplete, onItemsChange]);

  const updateItems = (next: ChecklistItem[]) => {
    if (!isControlled) {
      setInternalItems(next);
    }
    onItemsChange?.(next);
  };

  const slack = (ROW - side) / 2;
  const padV = Math.max(0, PAD - slack);
  const body = Math.max(side, line);
  const inset = (ROW - body) / 2;
  const slots = items.length + (spare ? 1 : 0);
  const floor = padV + ROW * slots;

  const leans = items.map(() => 0);
  for (let i = items.length - 2; i >= 0; i--) {
    const over = Math.max(0, (runs[i] ?? 0) - (runs[i + 1] ?? 0));
    leans[i] = clamp(leans[i + 1] + leanOf(over), 0, MAX_LEAN);
  }
  const touch = gapFor(leans, runs);
  const seat = floor - inset - body;
  const restTop = (i: number) => padV + i * ROW;
  const pileTop = (i: number) => seat - (items.length - 1 - i) * (body + touch);
  const drops = items.map((_, i) => Math.max(0, pileTop(i) - restTop(i)));
  const longest = Math.max(...drops, 1);

  const add = () => {
    const text = draft.trim();
    setAdding(false);
    setDraft("");
    if (!text || items.length >= MAX) return;
    updateItems([...items, { text, done: false }]);
  };

  return (
    <div
      className={cn(
        "chk font-sans transition-colors duration-300",
        isDark
          ? "bg-[#1b1b1b] text-[#ffffff] shadow-[0_0_0_1px_rgba(255,255,255,0.12)]"
          : "bg-[#ffffff] text-[#18181b] shadow-[0_0_0_1px_rgba(0,0,0,0.08)]",
        className
      )}
      data-theme={theme}
      style={{
        width: W,
        height: padV * 2 + ROW * slots,
        padding: `${padV}px ${PAD}px`,
        borderRadius: r,
        ...style,
      }}
    >
      <AnimatePresence initial={false}>
        {items.map((task, i) => (
          <Row
            key={`${i}-${task.text}`}
            label={task.text}
            on={task.done}
            side={side}
            bounce={bounce}
            still={still}
            fell={fell}
            drop={drops[i]}
            secs={DROP_MS * Math.sqrt(drops[i] / longest)}
            inset={inset}
            drift={DRIFT[i] ?? 0}
            tilt={leans[i] ?? 0}
            index={i}
            onRun={measure}
            layer={fell ? items.length - i : undefined}
            onToggle={() => {
              updateItems(
                items.map((t, k) => (k === i ? { ...t, done: !t.done } : t))
              );
            }}
          />
        ))}
      </AnimatePresence>

      {spare && (
        <div
          className="chk-add"
          data-hide={fell || undefined}
          style={{ height: ROW }}
          onClick={(e) => e.stopPropagation()}
        >
          <span
            className="chk-ghost"
            aria-hidden="true"
            style={{ width: side, height: side, borderRadius: side * 0.32 }}
          />
          {adding ? (
            <input
              className="chk-field"
              autoFocus
              value={draft}
              placeholder="New task"
              maxLength={40}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.stopPropagation();
                  add();
                }
                if (e.key === "Escape") {
                  e.stopPropagation();
                  setAdding(false);
                  setDraft("");
                }
              }}
              onBlur={add}
            />
          ) : (
            <button
              type="button"
              className="chk-new"
              onClick={() => {
                setAdding(true);
              }}
            >
              Add new task
            </button>
          )}
        </div>
      )}
    </div>
  );
}

function Row({
  label,
  on,
  side,
  bounce,
  still,
  fell,
  drop,
  secs,
  inset,
  drift,
  tilt,
  layer,
  index,
  onRun,
  onToggle,
}: {
  label: string;
  on: boolean;
  side: number;
  bounce: number;
  still: boolean;
  fell: boolean;
  drop: number;
  secs: number;
  inset: number;
  drift: number;
  tilt: number;
  layer?: number;
  index: number;
  onRun: (i: number, px: number, tall: number) => void;
  onToggle: () => void;
}) {
  const say = useRef<HTMLSpanElement | null>(null);
  useIsomorphicLayoutEffect(() => {
    const el = say.current;
    if (el) onRun(index, el.offsetLeft + el.offsetWidth, el.offsetHeight);
  }, [label, side, index, onRun]);

  const t = useSpring(on ? 1 : 0, clamp(bounce, 0, 100), still);
  const held = clamp(t, 0, 1);
  const cut = clamp((held - LAG) / RUN, 0, 1);

  const run = still ? 0 : secs;
  const up = Math.min(REBOUND, drop * 0.22);
  const land = {
    duration: run,
    times: [0, 0.66, 0.84, 1],
    ease: [...FALL_EASE],
  };
  const lean = { duration: run, ease: "easeIn" as const };

  return (
    <motion.button
      type="button"
      className="chk-row"
      role="checkbox"
      aria-checked={on}
      data-fell={fell || undefined}
      onClick={onToggle}
      style={
        {
          height: ROW,
          zIndex: layer,
          "--slip": `${inset}px`,
        } as React.CSSProperties
      }
      initial={false}
      exit={{ opacity: 0, transition: { duration: 0.16 } }}
      animate={
        fell
          ? { y: [0, drop, drop - up, drop], x: drift, rotate: tilt }
          : { y: 0, x: 0, rotate: 0 }
      }
      transition={
        fell
          ? { y: land, x: lean, rotate: lean }
          : { type: "spring", stiffness: 380, damping: 34, mass: 0.9 }
      }
    >
      <span
        className="chk-box"
        style={{
          width: side,
          height: side,
          borderRadius: side * 0.32,
        }}
      >
        <span
          className="chk-fill"
          style={{
            borderRadius: side * 0.32,
            transform: `scale(${t.toFixed(4)})`,
          }}
        />
        <svg className="chk-tick" viewBox="0 0 24 24" aria-hidden="true">
          <path
            d="M6 12.4 L10.3 16.7 L18 7.6"
            pathLength={1}
            strokeDasharray={1}
            strokeDashoffset={1 - held}
          />
        </svg>
      </span>

      <span className="chk-say" ref={say}>
        <span className="chk-word" style={{ opacity: mix(1, 0.42, held) }}>
          {label}
        </span>
        <span
          className="chk-rule"
          aria-hidden="true"
          style={{ transform: `scaleX(${cut.toFixed(4)})` }}
        />
      </span>
    </motion.button>
  );
}

/* ══ Checklist ═════════════════════════════════════════════ */
.chk {
  box-sizing: border-box;
  overflow: hidden;
  position: relative;
  transition: height 420ms cubic-bezier(0.22, 1, 0.36, 1);
  font-family: inherit;
  user-select: none;
  -webkit-user-select: none;
}

/* Light Theme Variables */
.chk[data-theme="light"] {
  --chk-bg: #ffffff;
  --chk-ink: #18181b;
  --chk-border: rgba(0, 0, 0, 0.08);
  --chk-ring: rgba(24, 24, 27, 0.28);
  --chk-ghost: rgba(24, 24, 27, 0.16);
  --chk-placeholder: rgba(24, 24, 27, 0.32);
  --chk-tick: #ffffff;
  background-color: var(--chk-bg);
  color: var(--chk-ink);
  box-shadow: 0 0 0 1px var(--chk-border);
}

/* Dark Theme Variables */
.chk[data-theme="dark"] {
  --chk-bg: #1b1b1b;
  --chk-ink: #ffffff;
  --chk-border: rgba(255, 255, 255, 0.12);
  --chk-ring: rgba(255, 255, 255, 0.32);
  --chk-ghost: rgba(255, 255, 255, 0.2);
  --chk-placeholder: rgba(255, 255, 255, 0.32);
  --chk-tick: #1b1b1b;
  background-color: var(--chk-bg);
  color: var(--chk-ink);
  box-shadow: 0 0 0 1px var(--chk-border);
}

.chk-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  position: relative;
  padding: 0;
  border: 0;
  border-radius: 10px;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

/* Inset pseudo-element for when row has fallen into the heap */
.chk-row[data-fell]::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: var(--slip, 9px);
  bottom: var(--slip, 9px);
  border-radius: 10px;
  background: var(--chk-bg, #ffffff);
  z-index: -1;
}

.chk-row:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px rgba(24, 24, 27, 0.3);
}

.chk[data-theme="dark"] .chk-row:focus-visible {
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.4);
}

/* Spare Add Task Row */
.chk-add {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  font-size: 14px;
  font-weight: 400;
  letter-spacing: -0.01em;
  transition: opacity 220ms ease;
}

.chk-add[data-hide] {
  opacity: 0;
  pointer-events: none;
}

.chk-ghost {
  flex: none;
  box-shadow: inset 0 0 0 1.5px var(--chk-ghost, rgba(24, 24, 27, 0.16));
}

.chk-new {
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  text-align: left;
  cursor: pointer;
  opacity: 0.38;
  transition: opacity 160ms ease;
}

.chk-new:hover {
  opacity: 0.72;
}

.chk-field {
  flex: 1;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  outline: none;
}

.chk-field::placeholder {
  color: var(--chk-placeholder, rgba(24, 24, 27, 0.32));
}

/* Checkbox Frame */
.chk-box {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  overflow: hidden;
  box-shadow: inset 0 0 0 1.5px var(--chk-ring, rgba(24, 24, 27, 0.28));
}

/* Checkbox Fill */
.chk-fill {
  position: absolute;
  inset: 0;
  background: var(--chk-ink, #18181b);
  transform-origin: center;
}

/* Drawn SVG Tick */
.chk-tick {
  position: relative;
  width: 68%;
  height: 68%;
  overflow: visible;
  fill: none;
  stroke: var(--chk-tick, #ffffff);
  stroke-width: 2.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Row Label Text */
.chk-say {
  position: relative;
  display: inline-block;
  font-size: 14px;
  font-weight: 400;
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.chk-word {
  display: inline-block;
}

/* Strikethrough Rule */
.chk-rule {
  position: absolute;
  left: 0;
  right: 0;
  top: 46%;
  height: 1.5px;
  border-radius: 2px;
  background: currentColor;
  transform-origin: left center;
  pointer-events: none;
}
